import{_ as t,o,c as a,a5 as r}from"./chunks/framework.BjM_ivYE.js";const u=JSON.parse('{"title":"Docking keeps retrying","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/troubleshooting/docking-retry.md","filePath":"manual/troubleshooting/docking-retry.md","lastUpdated":1790646309000}'),i={name:"manual/troubleshooting/docking-retry.md"};function n(s,e,l,d,c,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="docking-keeps-retrying" tabindex="-1">Docking keeps retrying <a class="header-anchor" href="#docking-keeps-retrying" aria-label="Permalink to &quot;Docking keeps retrying&quot;">​</a></h1><p>The robot fails to dock at the charging station and keeps trying again. In most cases <strong>the marker is not visible</strong>; the next most common cause is <strong>an alignment offset</strong>.</p><h2 id="first-checks" tabindex="-1">First checks <a class="header-anchor" href="#first-checks" aria-label="Permalink to &quot;First checks {#first-checks}&quot;">​</a></h2><ul><li>Confirm the robot is <strong>within 3 m</strong> of the docking station.</li><li>Confirm the robot&#39;s <strong>front or rear camera is facing the docking station</strong>.</li><li>Check the marker on the docking station for obstructions, dirt or water.</li><li>Confirm the docking station is powered.</li></ul><h2 id="marker-not-found" tabindex="-1">The marker is not recognized <a class="header-anchor" href="#marker-not-found" aria-label="Permalink to &quot;The marker is not recognized {#marker-not-found}&quot;">​</a></h2><p><strong>Cause:</strong> Docking works by locating the marker on the docking station. Recognition fails if any of the following applies.</p><ul><li>The distance is <strong>more than 3 m</strong>.</li><li>Only part of the marker is visible. The marker is a group of several patterns on one board, and <strong>enough of them must be fully visible</strong> for the pose to be computed.</li><li>The marker is hard to see because of shade, backlight or reflections.</li></ul><p><strong>Fix:</strong></p><ol><li>Move the robot <strong>within 3 m, in front of</strong> the docking station.</li><li>Clean the marker surface and remove anything blocking it.</li><li>If there is direct sunlight or strong reflection, change the lighting or move the station.</li><li>Start docking again.</li></ol><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE</p><p>Do not move the robot by hand while docking. The docking station must also be fixed to the floor.</p></div></div><h2 id="alignment-off" tabindex="-1">The marker is recognized but the alignment is off <a class="header-anchor" href="#alignment-off" aria-label="Permalink to &quot;The marker is recognized but the alignment is off {#alignment-off}&quot;">​</a></h2><p><strong>Cause:</strong> The robot reaches the front of the docking station but is slightly out of position laterally or front-to-back. The alignment offsets need adjusting.</p><p><strong>Fix:</strong> Adjust <code>Offset X</code> and <code>Offset Y</code> following <a href="#dock-parameters">Adjusting the docking parameters</a> below.</p><h2 id="dock-parameters" tabindex="-1">Adjusting the docking parameters <a class="header-anchor" href="#dock-parameters" aria-label="Permalink to &quot;Adjusting the docking parameters {#dock-parameters}&quot;">​</a></h2><p>The alignment offsets and retry counts can be viewed and changed under <strong>Robot settings → Calibration → Docking calibration</strong> in the app.</p><h3 id="preparation" tabindex="-1">Preparation <a class="header-anchor" href="#preparation" aria-label="Permalink to &quot;Preparation {#preparation}&quot;">​</a></h3><ul><li>Move the robot to a place where docking can be tested.</li><li>Keep the surrounding area clear of obstacles.</li><li>The app must be connected to the robot.</li></ul><h3 id="procedure" tabindex="-1">Procedure <a class="header-anchor" href="#procedure" aria-label="Permalink to &quot;Procedure {#procedure}&quot;">​</a></h3><ol><li>Open <strong>Robot settings → Calibration</strong> in the app and scroll down to <strong>Docking calibration</strong>. The current values load automatically when you enter the screen; press <code>Reload</code> to read them again.</li><li>Edit the values that are off.</li><li>Press <code>Apply</code> to store them on the robot. The screen refreshes with the values the robot actually accepted and shows <em>Applied (re-confirmed with robot values)</em>.</li><li>Repeat steps <strong>2–3</strong> until docking is stable.</li><li>Once adjusted, use the docking function as usual.</li></ol><p>To restore the originals press <code>Defaults</code> — it only fills the fields with the factory values, so <strong>you still have to press <code>Apply</code> to store them on the robot.</strong></p><h3 id="parameters" tabindex="-1">Adjustable parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Adjustable parameters {#parameters}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>Meaning</th><th>Default</th></tr></thead><tbody><tr><td><code>Offset X (m)</code></td><td>Position correction along the robot&#39;s X axis</td><td>—</td></tr><tr><td><code>Offset Y (m)</code></td><td>Position correction along the robot&#39;s Y axis</td><td>—</td></tr><tr><td><code>Req Count</code></td><td>Upper limit on consecutive failed responses when requesting the marker (charger) pose</td><td>300</td></tr><tr><td><code>Try Count</code></td><td>How many times docking is retried after a failure</td><td>10</td></tr></tbody></table><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p>Raising the retry counts is not a real fix. If the marker cannot be seen, a higher count only repeats the failure for longer. Check the recognition conditions above first.</p></div></div><h2 id="still-stuck" tabindex="-1">Still stuck? <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck? {#still-stuck}&quot;">​</a></h2><p>Open <strong><a href="/RBQ/manual/gui/logs.html#real-time">Logs → Real Time</a></strong>, start docking and read the messages that appear. Phrases such as <code>Marker Not Found</code> or <code>too far</code> are useful to include.</p><p>See <a href="/RBQ/manual/operation/charging.html">Charging</a> for docking station installation requirements.</p><p><strong>→ <a href="/RBQ/manual/support/">Contact us</a></strong></p>',27)])])}const p=t(i,[["render",n]]);export{u as __pageData,p as default};
